WITH src AS (SELECT * FROM transactions WHERE amount <= 1400 AND amount IS NOT NULL), agg AS (SELECT CASE WHEN amount >= 4200 THEN 'high' WHEN amount >= 1500 THEN 'mid' ELSE 'low' END AS amount_bucket, MONTH(txn_time) AS txn_month, CONCAT_WS(', ', SORT_ARRAY(COLLECT_SET(merchant))) AS merchant_values FROM src GROUP BY CASE WHEN amount >= 4200 THEN 'high' WHEN amount >= 1500 THEN 'mid' ELSE 'low' END, MONTH(txn_time)) SELECT amount_bucket, txn_month, merchant_values FROM agg;
